import { readFileSync } from "node:fs";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { verifyWebhookSignature } from "./webhooks.js";

interface SignatureFixtures {
  secret: string;
  cases: Array<{ name: string; body: string; timestamp?: number; signatureHeader: string }>;
}

// Generated by the indexer's own signer (apps/indexer/scripts/generate-webhook-fixtures.ts), and re-checked
// against it by apps/indexer/test/webhook-signature.test.ts, so these can't drift from real deliveries.
const fixtures = JSON.parse(
  readFileSync(new URL("../../../apps/indexer/test/fixtures/webhook-signatures.json", import.meta.url), "utf8")
) as SignatureFixtures;

const fixture = (name: string) => {
  const found = fixtures.cases.find((c) => c.name === name);
  if (!found) throw new Error(`missing fixture ${name}`);
  return found;
};

const legacy = fixture("legacy");
const timestamped = fixture("timestamped");
const { secret } = fixtures;

describe("verifyWebhookSignature — legacy sha256= format", () => {
  it.each(fixtures.cases.filter((c) => c.timestamp === undefined))("accepts indexer fixture: $name", async (c) => {
    await expect(verifyWebhookSignature({ body: c.body, signatureHeader: c.signatureHeader, secret })).resolves.toBe(
      true
    );
  });

  it("accepts the body as bytes (Uint8Array and ArrayBuffer)", async () => {
    const bytes = new TextEncoder().encode(legacy.body);
    await expect(verifyWebhookSignature({ body: bytes, signatureHeader: legacy.signatureHeader, secret })).resolves.toBe(
      true
    );
    await expect(
      verifyWebhookSignature({ body: bytes.buffer as ArrayBuffer, signatureHeader: legacy.signatureHeader, secret })
    ).resolves.toBe(true);
  });

  it("accepts an upper-case hex digest and surrounding whitespace", async () => {
    const header = ` sha256=${legacy.signatureHeader.slice(7).toUpperCase()} `;
    await expect(verifyWebhookSignature({ body: legacy.body, signatureHeader: header, secret })).resolves.toBe(true);
  });

  it("rejects a tampered body", async () => {
    const body = legacy.body.replace("1250000000", "9250000000");
    await expect(verifyWebhookSignature({ body, signatureHeader: legacy.signatureHeader, secret })).resolves.toBe(false);
  });

  it("rejects the wrong secret", async () => {
    await expect(
      verifyWebhookSignature({ body: legacy.body, signatureHeader: legacy.signatureHeader, secret: "nope" })
    ).resolves.toBe(false);
  });

  it.each([
    ["missing", undefined],
    ["null", null],
    ["empty", ""],
    ["no prefix", legacy.signatureHeader.slice(7)],
    ["wrong algorithm", legacy.signatureHeader.replace("sha256=", "sha1=")],
    ["truncated", legacy.signatureHeader.slice(0, -2)],
    ["non-hex", `sha256=${"z".repeat(64)}`]
  ])("rejects a %s signature header without throwing", async (_label, signatureHeader) => {
    await expect(verifyWebhookSignature({ body: legacy.body, signatureHeader, secret })).resolves.toBe(false);
  });

  it("rejects an empty secret", async () => {
    await expect(
      verifyWebhookSignature({ body: legacy.body, signatureHeader: legacy.signatureHeader, secret: "" })
    ).resolves.toBe(false);
  });
});

describe("verifyWebhookSignature — timestamped format", () => {
  const ts = timestamped.timestamp!;

  beforeEach(() => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date((ts + 30) * 1000));
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  const verify = (overrides: Partial<Parameters<typeof verifyWebhookSignature>[0]> = {}) =>
    verifyWebhookSignature({
      body: timestamped.body,
      signatureHeader: timestamped.signatureHeader,
      timestampHeader: String(ts),
      secret,
      ...overrides
    });

  it("accepts the indexer fixture within tolerance", async () => {
    await expect(verify()).resolves.toBe(true);
  });

  it("rejects a timestamp older than the default 300s tolerance", async () => {
    vi.setSystemTime(new Date((ts + 301) * 1000));
    await expect(verify()).resolves.toBe(false);
  });

  it("rejects a timestamp too far in the future", async () => {
    vi.setSystemTime(new Date((ts - 301) * 1000));
    await expect(verify()).resolves.toBe(false);
  });

  it("honours a custom toleranceSeconds", async () => {
    vi.setSystemTime(new Date((ts + 3600) * 1000));
    await expect(verify()).resolves.toBe(false);
    await expect(verify({ toleranceSeconds: 3600 })).resolves.toBe(true);
  });

  it("rejects a replay with a different timestamp", async () => {
    await expect(verify({ timestampHeader: String(ts + 1) })).resolves.toBe(false);
  });

  it("rejects a timestamped signature checked as legacy, and vice versa", async () => {
    await expect(verify({ timestampHeader: undefined })).resolves.toBe(false);
    await expect(verify({ signatureHeader: legacy.signatureHeader })).resolves.toBe(false);
  });

  it.each(["", "abc", "1.5", "-1", "1e9"])("rejects a malformed timestamp header %j", async (timestampHeader) => {
    await expect(verify({ timestampHeader })).resolves.toBe(false);
  });
});

describe("verifyWebhookSignature — runtime portability", () => {
  it("does not depend on node:crypto (WebCrypto only, so it runs in edge runtimes)", () => {
    const source = readFileSync(new URL("./webhooks.ts", import.meta.url), "utf8");
    expect(source).not.toMatch(/from\s+["'](node:)?crypto["']/);
  });
});
